css:
.certification-container {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    color: #333;
    max-width: 800px;
    margin: 0 auto;
    padding: 20px;
    border: 8px solid double #4a5568;
    border-radius: 4px;
    background-color: #fff;
}

.cert-header {
    text-align: center;
    border-bottom: 3px solid #2b6cb0;
    padding-bottom: 20px;
    margin-bottom: 30px;
}

.cert-header h1 {
    margin: 0;
    font-size: 28px;
    color: #2b6cb0;
    text-transform: uppercase;
    letter-spacing: 2px;
}

.subtitle {
    margin: 10px 0 0 0;
    font-size: 14px;
    color: #718096;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.cert-details {
    margin-bottom: 30px;
    background-color: #f7fafc;
    padding: 20px;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
}

.detail-row {
    display: flex;
    justify-content: space-between;
    margin-bottom: 15px;
}

.detail-row:last-child {
    margin-bottom: 0;
}

.detail-col {
    width: 48%;
}

.text-right {
    text-align: right;
}

.label {
    font-size: 12px;
    color: #a0aec0;
    text-transform: uppercase;
    font-weight: bold;
    display: block;
    margin-bottom: 4px;
}

.value {
    font-size: 16px;
    font-weight: bold;
    color: #2d3748;
}

.cert-body h3 {
    font-size: 18px;
    color: #2b6cb0;
    border-bottom: 1px solid #cbd5e0;
    padding-bottom: 10px;
    margin-bottom: 15px;
}

.cert-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 40px;
}

.cert-table th, .cert-table td {
    border: 1px solid #e2e8f0;
    padding: 10px;
    text-align: left;
    font-size: 13px;
}

.cert-table th {
    background-color: #edf2f7;
    color: #4a5568;
    font-weight: bold;
    text-transform: uppercase;
    font-size: 11px;
}

.cert-table td {
    color: #2d3748;
}

.fail-row td {
    background-color: #fff5f5;
    color: #c53030;
}

.badge {
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: bold;
    text-transform: uppercase;
}

.badge-success {
    background-color: #c6f6d5;
    color: #22543d;
    border: 1px solid #9ae6b4;
}

.badge-danger {
    background-color: #fed7d7;
    color: #742a2a;
    border: 1px solid #feb2b2;
}

.cert-footer {
    display: flex;
    justify-content: space-between;
    margin-top: 60px;
    padding-top: 20px;
}

.signature-block {
    width: 40%;
    text-align: center;
    position: relative;
}

.line {
    border-top: 1px solid #718096;
    margin-bottom: 10px;
}

.signature-block strong {
    display: block;
    font-size: 12px;
    color: #4a5568;
    text-transform: uppercase;
}

.signature-block p {
    margin: 5px 0 0 0;
    font-size: 14px;
    color: #2d3748;
    font-weight: bold;
}

.seal {
    position: absolute;
    top: -50px;
    left: 50%;
    transform: translateX(-50%);
    width: 80px;
    height: 80px;
    border: 2px dashed #cbd5e0;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #a0aec0;
    font-size: 12px;
    font-weight: bold;
    opacity: 0.5;
}
